from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
base='https://us.humankinetics.com/'
records=[
('graduate-nsca-baseball-contents','Strength Training for Baseball — publisher overview and contents','products/strength-training-for-baseball','Publisher overview, table of contents, editors and publication details.','Organizes baseball preparation around demands, assessment, exercise methods and four seasonal phases.','Only the contents and publisher description were reviewed. Full chapter arguments, all 13 advertised tests and 34 sample programs were not inspected.'),
('graduate-nsca-baseball-position','Strength Training for Baseball — position demands excerpt','blogs/excerpt/understand-the-movement-needed-for-every-position-on-the-field','Public excerpt: position-specific movement requirements.','Provides an expert description of differing position demands.','Expert teaching context, not intervention evidence. Position categories do not establish an individual player’s capacity or a causal training effect.'),
('graduate-nsca-baseball-season','Strength Training for Baseball — postseason examples excerpt','blogs/excerpt/sample-training-program-table-for-high-school-athletes','Public excerpt: Table 12.1 high-school postseason circuit and Table 12.2 college postseason restoration context.','Illustrates postseason planning for different athlete levels.','The published examples concern school and college settings. Their prescriptions were not reproduced or treated as validated professional-baseball schedules.'),
('graduate-nsca-baseball-bench','Strength Training for Baseball — bench assessment excerpt','blogs/excerpt/1rm-or-estimated-1rm-bench-press','Public excerpt: purpose, equipment, procedures and coaching guidance; table images not transcribed.','Describes maximal or estimated upper-body pushing assessment and protocol alternatives.','Exercise, estimation method and reference population affect interpretation. No universal shoulder-safety, readiness or throwing-performance claim is adopted.'),
('graduate-nsca-baseball-throw','Strength Training for Baseball — medicine-ball exercise excerpt','blogs/excerpt/medicine-ball-blob-throw-between-legs-over-back','Public excerpt: starting position, movement and coaching guidance.','Demonstrates a medicine-ball movement.','Exercise instruction does not validate a field test or its relationship to baseball performance. No publisher figure was copied.')]
